    "options": [
      {
        "text": "Empiric broad-spectrum antifungal therapy as sole medical intervention",
        "correct": false,
        "explanation": "Incorrect: Antifungal therapy is inappropriate in the absence of documented microbiological or radiological evidence of invasive fungal disease."
      },
      {
        "text": "Intravenous loop diuretic administration in a hypovolemic or hypotensive patient",
        "correct": false,
        "explanation": "Incorrect: Administering potent loop diuretics during hypoperfusion exacerbates circulatory collapse and accelerates ischemic tubular injury."
      },
      {
        "text": "High-flow oxygen therapy via non-rebreather mask in acute hypercapnic respiratory failure",
        "correct": false,
        "explanation": "Incorrect: Uncontrolled high FiO2 in hypercapnic chronic lung disease abolishes hypoxic respiratory drive, precipitating carbon dioxide narcosis."
      },
      {
        "text": "Empiric aminoglycoside monotherapy for atypical community-acquired respiratory infection",
        "correct": false,
        "explanation": "Incorrect: Aminoglycosides lack reliable tissue penetration and intracellular activity against atypical respiratory organisms such as Mycoplasma."
      },
      {
        "text": "Lifelong oral magnesium and potassium chloride supplementation",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is lifelong oral magnesium and potassium chloride supplementation. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      }
    ],
    "explanation": "Educational Objective: Understand the diagnosis, guideline-directed management, and clinical rationale for Gitelman Syndrome with Hypokalemia, Hypomagnesemia, and Hypocalciuria.\\n\\nClinical Discussion: This clinical presentation corresponds to Gitelman Syndrome with Hypokalemia, Hypomagnesemia, and Hypocalciuria. The cornerstone of management involves lifelong oral magnesium and potassium chloride supplementation. Clinical decision-making prioritizes rapid diagnosis, stabilization, and adherence to established clinical guidelines. Alternative choices represent suboptimal management strategies, delayed interventions, or therapies lacking efficacy in this specific clinical presentation.",
    "objective": "Understand the guideline-directed management and pathophysiological basis of Gitelman Syndrome with Hypokalemia, Hypomagnesemia, and Hypocalciuria.",
